func codeEnvDefault(v ConnectFormView) string {
	if len(v.Envs) == 0 {
		return "production"
	}
	return ""
}

func codeMany(p PlatformInfo) string {
	switch p.Key {
	case "kubernetes":
		return "clusters"
	case "nomad", "lambda":
		return "regions"
	case "ecs":
		return "ECS clusters"
	case "swarm":
		return "swarms"
	}
	return "hosts"
}

